"""Exact integer dimension ladder generated by LEGO allocation fibers.

Let H_m(c) be the number of nonnegative allocations of c indistinguishable unit
objects among m slots.  Since H_1(c)=1 and an (m+1)-slot fiber is obtained by
choosing how many units enter the final one-slot block,

    H_(m+1)(c) = sum_{a=0}^c H_m(a).

Thus one dimension-raising step is exact finite prefix accumulation.  The
inverse dimension-lowering step is the adjacent integer difference

    H_m(c) = H_(m+1)(c) - H_(m+1)(c-1),

with H_(m+1)(-1)=0.

These are not calculus approximations; they are exact shadows of adding/removing
one LEGO placement freedom.
"""

from __future__ import annotations

from .lego_partition_fiber import hidden_allocation_multiplicity


def prefix_accumulate(values: tuple[int, ...]) -> tuple[int, ...]:
    if not isinstance(values, tuple) or not values:
        raise ValueError("values must be a non-empty tuple")
    if any(isinstance(value, bool) or not isinstance(value, int) for value in values):
        raise ValueError("values must be integers")
    total = 0
    result = []
    for value in values:
        total += value
        result.append(total)
    return tuple(result)


def adjacent_lower(values: tuple[int, ...]) -> tuple[int, ...]:
    """Boundary-aware adjacent difference with implicit previous value zero."""
    if not isinstance(values, tuple) or not values:
        raise ValueError("values must be a non-empty tuple")
    if any(isinstance(value, bool) or not isinstance(value, int) for value in values):
        raise ValueError("values must be integers")
    previous = 0
    result = []
    for value in values:
        result.append(value - previous)
        previous = value
    return tuple(result)


def allocation_row(capacity: int, maximum_total: int) -> tuple[int, ...]:
    if isinstance(maximum_total, bool) or not isinstance(maximum_total, int) or maximum_total < 0:
        raise ValueError("maximum_total must be a non-negative integer")
    return tuple(
        hidden_allocation_multiplicity(capacity, total)
        for total in range(maximum_total + 1)
    )


def raise_allocation_dimension(capacity: int, maximum_total: int) -> tuple[int, ...]:
    """Generate H_(m+1) from H_m by one exact prefix accumulation."""
    return prefix_accumulate(allocation_row(capacity, maximum_total))


def lower_allocation_dimension(capacity: int, maximum_total: int) -> tuple[int, ...]:
    """Recover H_(m-1) from H_m by one exact adjacent difference, m>=2."""
    if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity < 2:
        raise ValueError("capacity must be at least two")
    return adjacent_lower(allocation_row(capacity, maximum_total))


def dimension_ladder_identity(capacity: int, maximum_total: int) -> bool:
    """Check S(H_m)=H_(m+1) and D(H_(m+1))=H_m exactly."""
    current = allocation_row(capacity, maximum_total)
    raised = raise_allocation_dimension(capacity, maximum_total)
    expected_raised = allocation_row(capacity + 1, maximum_total)
    return raised == expected_raised and adjacent_lower(raised) == current
